const $=s=>document.querySelector(s),sleep=ms=>new Promise(r=>setTimeout(r,ms)),assert=(v,m)=>{if(!v)throw Error(m);};
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
const files=['app.js','engine.js','effects.js','extended-effects.js','extended-effects-worklet.js','panels.js','lpf-live-harness.js','fx-tempo-capture-worklet.js'];
async function identities(){const out={};for(const f of [...files,'lpf-kernel.js']){const r=await fetch(f,{cache:'no-store'});out[f]=r.ok?await hash(await r.arrayBuffer()):'absent';}return out;}
async function until(fn,label){const end=performance.now()+15000;while(!fn()){assert(performance.now()<end,label+' timed out');await sleep(10);}}
function base64(bytes){let s='';for(let i=0;i<bytes.length;i+=16384)s+=String.fromCharCode(...bytes.subarray(i,i+16384));return btoa(s);}
let app;
function parameters(values){$('[data-fx-params="0:0"]').click();for(const[k,v]of Object.entries(values))$(`[data-param="${k}"]`).value=String(v);$('#save-effect').click();}
function depth(value){const input=$('[data-fx-depth="0:0"]');input.value=String(value);input.dispatchEvent(new Event('input',{bubbles:true}));}
async function run(){const{engine,state}=app;$('#lpf-run').disabled=true;const before=new URL(location.href).searchParams.has('before'),r={startedAt:new Date().toISOString(),scope:'Actual production browser LPF advanced Save/depth controls, generated DC+two-tone engine buffer and post-master stereo PCM. Physical graph muted. Not file import, music/listening, native, hardware, exact vendor response, all rates or full FX parity.',criteria:{captureSeconds:1,commandAfterSeconds:.2,maxAdjacentSampleJump:.03,maximumMeanChange:.005},cases:[],errors:[]};const witnesses=[];
 const output=()=>{$('#lpf-original').textContent=JSON.stringify(r,null,2);$('#lpf-results').textContent=JSON.stringify({...r,cases:r.cases.map(c=>({...c,pcm:c.pcm?.map(p=>({...p,base64:'Retained in original'}))}))},null,2);};
 async function sample(name,action,{silence=false}={}){const c={name,silence};r.cases.push(c);$('#lpf-status').textContent='Running '+name;await sleep(300);const d=state.decks[0],voice=engine.voices.get(0);c.specBefore=structuredClone(state.fx[0][0]);c.positionBefore=engine.position(d);const id=r.cases.length;
  const jobs=witnesses.map(w=>new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('PCM capture timeout')),5000);w.port.onmessage=({data})=>{if(data.type==='done'&&data.id===id){clearTimeout(timer);resolve(data);}};w.port.postMessage({type:'capture',id,frames:Math.round(engine.ctx.sampleRate)});}));
  const at=engine.ctx.currentTime;await until(()=>engine.ctx.currentTime>=at+.2,'Pre-command capture');c.commandBefore=engine.ctx.currentTime;await action();c.commandAfter=engine.ctx.currentTime;c.specAfter=structuredClone(state.fx[0][0]);const raw=await Promise.all(jobs);c.pcm=[];c.metrics=[];
  for(const p of raw){const data=p.data,bytes=new Uint8Array(data.buffer);let finite=true,peak=0,jump=0,jumpAt=0;for(let i=0;i<data.length;i++){finite&&=Number.isFinite(data[i]);peak=Math.max(peak,Math.abs(data[i]));if(i&&Math.abs(data[i]-data[i-1])>jump){jump=Math.abs(data[i]-data[i-1]);jumpAt=i;}}const mean=(a,b)=>{let sum=0;for(let i=a;i<b;i++)sum+=data[i];return sum/(b-a);};c.pcm.push({startFrame:p.startFrame,frames:data.length,sha256:await hash(bytes),base64:base64(bytes)});c.metrics.push({finite,peak,maxAdjacentJump:jump,jumpAt,meanBefore:mean(Math.round(.05*data.length),Math.round(.15*data.length)),meanAfter:mean(Math.round(.8*data.length),Math.round(.9*data.length))});}
  c.voicePreserved=engine.voices.get(0)===voice;c.positionAfter=engine.position(d);c.playing=d.playing;c.passed=c.metrics.every(m=>m.finite&&(silence?m.peak<1e-6:m.maxAdjacentJump<r.criteria.maxAdjacentSampleJump&&Math.abs(m.meanAfter-m.meanBefore)<r.criteria.maximumMeanChange))&&(silence||c.voicePreserved&&c.playing);output();}
 try{r.sourceBefore=await identities();engine.init();engine.audioMonitor.mutePhysical(true);await engine.resume();assert(engine.audioMonitor.snapshot().physicalMuted,'Physical graph must be muted');await until(()=>!state.analysis,'Initial analysis');for(const d of state.decks)engine.pause(d);for(const bank of state.fx)for(const slot of bank)slot.on=false;
  const d=state.decks[0],b=engine.ctx.createBuffer(2,engine.ctx.sampleRate*60,engine.ctx.sampleRate);for(let ch=0;ch<2;ch++)for(let i=0;i<b.length;i++)b.getChannelData(ch)[i]=.15+.02*Math.sin(2*Math.PI*100*i/b.sampleRate)+.02*Math.sin(2*Math.PI*2000*i/b.sampleRate);Object.assign(d.track,{duration:60,bpm:120,grid:0,analyzed:true});Object.assign(d,{rate:1,position:0,keylock:false,keyShift:0,reverse:false,loop:false,sync:false,syncState:'off'});engine.buffers.set(d.track.id,b);engine.clearDeckScratchCache(0);engine.mix(0,'level',.8);r.sampleRate=engine.ctx.sampleRate;
  await engine.ctx.audioWorklet.addModule(new URL('./fx-tempo-capture-worklet.js',import.meta.url));const split=engine.ctx.createChannelSplitter(2);engine.masterOutput.output.connect(split);for(let ch=0;ch<2;ch++){const w=new AudioWorkletNode(engine.ctx,'open-play-fx-tempo-capture-test',{numberOfInputs:1,numberOfOutputs:1,outputChannelCount:[1],channelCount:1,channelCountMode:'explicit',channelInterpretation:'discrete'});split.connect(w,ch);w.connect(engine.ctx.destination);witnesses.push(w);}
  $('[data-panel="fx"]').click();depth(100);parameters({Slope:'6 dB','Min Freq':'400 Hz','Max Freq':'400 Hz'});$('[data-fx-on="0:0"]').click();$('[data-action="play"][data-deck="0"]').click();await until(()=>d.playing&&!d.processing,'Playback');
  await sample('6dB live cutoff400→800',()=>parameters({'Min Freq':'800 Hz','Max Freq':'800 Hz'}));
  if(!before){await sample('6dB live depth100→50 with variable cutoff',()=>{parameters({'Min Freq':'400 Hz','Max Freq':'4000 Hz'});depth(50);});await sample('Live slope6→18 without transport restart',()=>parameters({Slope:'18 dB'}));await sample('18dB live cutoff→2000',()=>parameters({'Min Freq':'2000 Hz','Max Freq':'2000 Hz'}));await sample('Live slope18→6',()=>parameters({Slope:'6 dB'}));await sample('Return to24dB/cutoff500/depth100',()=>{parameters({Slope:'24 dB','Min Freq':'500 Hz','Max Freq':'500 Hz'});depth(100);});}
  $('[data-action="play"][data-deck="0"]').click();await until(()=>!d.playing,'Normal Stop');await sample('Normal Stop produces silence',()=>{},{silence:true});
 }catch(e){r.errors.push({message:e.message,stack:e.stack});}finally{for(const d of state.decks)engine.pause(d);for(const w of witnesses){w.disconnect();w.port.close();}r.sourceAfter=await identities();r.sourceStable=JSON.stringify(r.sourceBefore)===JSON.stringify(r.sourceAfter);r.completed=r.sourceStable&&!r.errors.length&&r.cases.length===(before?2:7)&&r.cases.every(c=>c.passed);r.finishedAt=new Date().toISOString();output();const link=$('#lpf-download');link.href=URL.createObjectURL(new Blob([JSON.stringify(r,null,2)],{type:'application/json'}));link.download='lpf-live-original.json';link.hidden=false;$('#lpf-status').textContent=r.completed?'Scoped live LPF workflow passed; stopped':'Captured LPF failures; stopped';}}
$('#lpf-run').onclick=()=>run();
async function boot(){const parsed=new DOMParser().parseFromString(await(await fetch('index.html')).text(),'text/html');for(const n of [...parsed.body.children])if(n.tagName!=='SCRIPT')document.body.append(n);await import('./app.js');await until(()=>window.openPlay?.state.decks[0].track,'Actual app');app=window.openPlay;$('#lpf-run').disabled=false;$('#lpf-status').textContent='Ready';}boot().catch(e=>$('#lpf-status').textContent=e.message);
